590	
591	function shuffle(a){for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
592	
593	let answers={};
594	document.querySelectorAll('[data-question]').forEach((q,qi)=>{
595	  const list=q.querySelector('.options');
596	  const fb=q.querySelector('.feedback');
597	  shuffle([...list.children]).forEach(li=>list.appendChild(li));
598	  list.querySelectorAll('li').forEach(li=>{
599	    li.addEventListener('click',()=>{
600	      if(li.classList.contains('locked'))return;
601	      list.querySelectorAll('li').forEach(x=>x.classList.add('locked'));
602	      const correct=li.dataset.correct==='true';
603	      li.classList.add(correct?'correct':'wrong');
604	      if(!correct)list.querySelectorAll('[data-correct="true"]').forEach(x=>x.classList.add('correct'));
605	      answers[qi]=correct;
606	      fb.style.display='block';
607	      fb.className='feedback '+(correct?'ok':'bad');
608	      fb.textContent=(correct?'✓ Correct. ':'✗ Not quite. ')+li.dataset.why;
609	    });
610	  });
611	});
612	
613	function scoreQuiz(){
614	  const total=document.querySelectorAll('[data-question]').length;
615	  const got=Object.values(answers).filter(Boolean).length;
616	  const answered=Object.keys(answers).length;
617	  const sb=document.getElementById('quiz-score');
618	  sb.style.display='block';
619	  const pct=answered?Math.round(got/total*100):0;
620	  if(answered<total){sb.style.background='#1e2a4a';sb.style.borderColor='#60a5fa';
621	    sb.innerHTML=`<strong>${got}/${answered}</strong> answered (${total-answered} skipped)`;}
622	  else if(pct===100){sb.style.background='#1a3a2a';sb.style.borderColor='#34d399';
623	    sb.innerHTML='🎉 <strong>5/5</strong> — Perfect! Mark section 8 complete.';}
624	  else if(pct>=60){sb.style.background='#2a2a1a';sb.style.borderColor='#fbbf24';
625	    sb.innerHTML=`<strong>${got}/5</strong> (${pct}%) — Good. Review the missed ones.`;}
626	  else{sb.style.background='#3a1a1a';sb.style.borderColor='#f87171';
627	    sb.innerHTML=`<strong>${got}/5</strong> (${pct}%) — Re-read sections 1–4, then retry.`;}
628	}
